 if(el.applyTextEdit)el.applyTextEdit.addEventListener('click',()=>{if(!selectedText)return;const value=el.inspectorText.value;if(!value.trim()){status('Enter replacement text first.');return;}remember();const view=selectedText.viewport,topLeft=view.convertToPdfPoint(selectedText.left,selectedText.top),bottomRight=view.convertToPdfPoint(selectedText.left+selectedText.width,selectedText.top+selectedText.height);const x=Math.min(topLeft[0],bottomRight[0]),y=Math.min(topLeft[1],bottomRight[1]),pdfWidth=Math.abs(bottomRight[0]-topLeft[0]),pdfHeight=Math.abs(bottomRight[1]-topLeft[1]);textEdits=textEdits.filter(e=>!(e.pageIndex===selectedText.pageIndex&&e.original===selectedText.original));textEdits.push({pageIndex:selectedText.pageIndex,original:selectedText.original,text:value,x,y,pdfWidth,pdfHeight,fontSize:Number(el.inspectorFontSize.value)||12,bold:!!el.inspectorBold.checked,align:el.inspectorAlignment.value||'left',fontFamily:el.inspectorFontFamily.value||'Helvetica',color:el.inspectorFontColor.value||'#17233c',opacity:Math.max(0,Math.min(100,Number(el.inspectorOpacity.value)||100))});selectedText.span.textContent=value;selectedText.span.style.fontSize=(Number(el.inspectorFontSize.value)||12)+'px';selectedText.span.style.fontWeight=el.inspectorBold.checked?'700':'400';selectedText.span.style.fontFamily=el.inspectorFontFamily.value==='TimesRoman'?'serif':el.inspectorFontFamily.value==='Courier'?'monospace':el.inspectorFontFamily.value==='CustomFont'?'"'+customFontName+'",sans-serif':'Arial, sans-serif';selectedText.span.style.color=el.inspectorFontColor.value||'#17233c';selectedText.span.style.opacity=String(Math.max(0,Math.min(100,Number(el.inspectorOpacity.value)||100))/100);selectedText.span.style.textAlign=el.inspectorAlignment.value||'left';selectedText.span.classList.add('edited');selectedText.span.classList.remove('selected');selectedText=null;el.applyTextEdit.disabled=true;status('Text edit applied to preview. Export PDF to save it.');});
